CREATE DATABASE IF NOT EXISTS `islamia_college_db` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `islamia_college_db`;

SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS `password_resets`;
DROP TABLE IF EXISTS `login_attempts`;
DROP TABLE IF EXISTS `users`;
DROP TABLE IF EXISTS `loans_and_advances`;
DROP TABLE IF EXISTS `asset_payment_installments`;
DROP TABLE IF EXISTS `capital_assets`;
DROP TABLE IF EXISTS `campus_expenses`;
DROP TABLE IF EXISTS `staff_payroll`;
DROP TABLE IF EXISTS `staff_members`;
DROP TABLE IF EXISTS `academic_positions`;
DROP TABLE IF EXISTS `board_examinations`;
DROP TABLE IF EXISTS `fee_transactions`;
DROP TABLE IF EXISTS `enrollments`;
DROP TABLE IF EXISTS `students`;
DROP TABLE IF EXISTS `batches`;
DROP TABLE IF EXISTS `courses`;
DROP TABLE IF EXISTS `departments`;

SET FOREIGN_KEY_CHECKS = 1;


CREATE TABLE `departments` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `dept_name` VARCHAR(100) NOT NULL UNIQUE,
    `dept_code` VARCHAR(20) NOT NULL UNIQUE,
    `description` VARCHAR(255) NULL,
    `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE `courses` (
    `department_id` INT NULL,
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `course_code` VARCHAR(50) NOT NULL UNIQUE,
    `course_name` VARCHAR(150) NOT NULL,
    `category` VARCHAR(100) NOT NULL DEFAULT 'General',
    `duration` VARCHAR(50) NULL,
    `standard_fee` DECIMAL(10,2) NOT NULL DEFAULT 0.00,
    `ttb_exam_fee` DECIMAL(10,2) NOT NULL DEFAULT 0.00,
    `description` TEXT NULL,
    `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    INDEX `idx_course_category` (`category`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE `batches` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `batch_code` VARCHAR(50) NOT NULL UNIQUE,
    `batch_name` VARCHAR(150) NOT NULL,
    `course_id` INT NOT NULL,
    `start_date` DATE NULL,
    `end_date` DATE NULL,
    `status` ENUM('active', 'completed', 'upcoming') NOT NULL DEFAULT 'active',
    `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT `fk_batch_course` FOREIGN KEY (`course_id`) REFERENCES `courses` (`id`) ON DELETE RESTRICT,
    INDEX `idx_batch_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE `students` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `student_reg_no` VARCHAR(50) NOT NULL UNIQUE,
    `full_name` VARCHAR(150) NOT NULL,
    `father_name` VARCHAR(150) NULL,
    `contact_number` VARCHAR(30) NULL,
    `secondary_contact` VARCHAR(30) NULL,
    `cnic` VARCHAR(25) NULL,
    `date_of_birth` DATE NULL,
    `email` VARCHAR(100) NULL,
    `address` VARCHAR(255) NULL,
    `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    `updated_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    INDEX `idx_student_name` (`full_name`),
    INDEX `idx_student_contact` (`contact_number`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE `enrollments` (
    `course_id` INT NULL,
    `academic_session` VARCHAR(100) NULL,
    `class_level` VARCHAR(100) NULL,

    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `student_id` INT NOT NULL,
    `batch_id` INT NOT NULL,
    `roll_number` VARCHAR(50) NULL,
    `enrollment_date` DATE NULL,
    `total_agreed_fee` DECIMAL(10,2) NOT NULL DEFAULT 0.00,
    `admission_fee` DECIMAL(10,2) NOT NULL DEFAULT 0.00,
    `discount_amount` DECIMAL(10,2) NOT NULL DEFAULT 0.00,
    `receipt_slip_no` VARCHAR(50) NULL,
    `tuition_class` VARCHAR(50) NULL,
    `tuition_subjects` VARCHAR(200) NULL,
    `status` ENUM('active', 'completed', 'dropped') NOT NULL DEFAULT 'active',
    `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT `fk_enroll_student` FOREIGN KEY (`student_id`) REFERENCES `students` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `fk_enroll_batch` FOREIGN KEY (`batch_id`) REFERENCES `batches` (`id`) ON DELETE RESTRICT,
    INDEX `idx_enroll_roll` (`roll_number`),
    INDEX `idx_enroll_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE `fee_transactions` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `enrollment_id` INT NOT NULL,
    `semester` TINYINT DEFAULT 1,
    `installment_no` TINYINT DEFAULT 1,
    `receipt_no` VARCHAR(50) NULL,
    `receipt_voucher_no` VARCHAR(50) NULL,
    `amount_paid` DECIMAL(10,2) NOT NULL DEFAULT 0.00,
    `due_amount` DECIMAL(10,2) NOT NULL DEFAULT 0.00,
    `fine_amount` DECIMAL(10,2) NOT NULL DEFAULT 0.00,
    `discount_amount` DECIMAL(10,2) NOT NULL DEFAULT 0.00,
    `payment_date` DATE NULL,
    `payment_method` VARCHAR(50) NOT NULL DEFAULT 'cash',
    `payment_mode` VARCHAR(50) NOT NULL DEFAULT 'cash',
    `reference_no` VARCHAR(100) NULL,
    `bank_name` VARCHAR(100) NULL,
    `cheque_date` DATE NULL,
    `received_by` VARCHAR(100) NULL,
    `remarks` VARCHAR(255) NULL,
    `is_cancelled` TINYINT(1) NOT NULL DEFAULT 0,
    `cancellation_reason` VARCHAR(255) NULL,
    `cancelled_by` VARCHAR(100) NULL,
    `cancelled_at` DATETIME NULL,
    `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT `fk_tx_enrollment` FOREIGN KEY (`enrollment_id`) REFERENCES `enrollments` (`id`) ON DELETE RESTRICT,
    INDEX `idx_tx_payment_date` (`payment_date`),
    INDEX `idx_fee_receipt_no` (`receipt_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE `board_examinations` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `student_id` INT NOT NULL,
    `board_name` VARCHAR(100) NOT NULL DEFAULT 'Trade Testing Board (TTB) Peshawar',
    `board_registration_no` VARCHAR(100) NULL,
    `board_roll_no` VARCHAR(50) NULL,
    `trade_course_name` VARCHAR(150) NOT NULL,
    `registration_date` DATE NULL,
    `exam_fee_paid` DECIMAL(10,2) NOT NULL DEFAULT 0.00,
    `exam_status` ENUM('enrolled', 'pass', 'fail', 'absent') NOT NULL DEFAULT 'enrolled',
    `marks_obtained` DECIMAL(6,2) NULL,
    `total_marks` DECIMAL(6,2) NULL,
    `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT `fk_board_student` FOREIGN KEY (`student_id`) REFERENCES `students` (`id`) ON DELETE CASCADE,
    INDEX `idx_board_roll` (`board_roll_no`),
    INDEX `idx_board_status` (`exam_status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE `academic_positions` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `student_id` INT NULL,
    `session_name` VARCHAR(100) NOT NULL,
    `batch_name` VARCHAR(100) NOT NULL,
    `position_rank` VARCHAR(50) NOT NULL,
    `student_name` VARCHAR(150) NOT NULL,
    `marks_obtained` INT NULL,
    `total_marks` INT NULL,
    `award_title` VARCHAR(200) NULL,
    `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT `fk_pos_student` FOREIGN KEY (`student_id`) REFERENCES `students` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE `staff_members` (
    `profile_photo` VARCHAR(255) NULL,
    `salary_type` VARCHAR(20) NOT NULL DEFAULT 'fixed',
    `salary_percentage` DECIMAL(5,2) NOT NULL DEFAULT 0.00,

    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `staff_code` VARCHAR(50) NOT NULL UNIQUE,
    `full_name` VARCHAR(150) NOT NULL,
    `designation` VARCHAR(100) NOT NULL,
    `phone` VARCHAR(30) NULL,
    `base_salary` DECIMAL(10,2) NOT NULL DEFAULT 0.00,
    `is_active` BOOLEAN NOT NULL DEFAULT TRUE,
    `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE `staff_payroll` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `staff_id` INT NOT NULL,
    `month_name` VARCHAR(30) NOT NULL,
    `year_num` INT NOT NULL,
    `salary_agreed` DECIMAL(10,2) NOT NULL DEFAULT 0.00,
    `installment_p1` DECIMAL(10,2) NOT NULL DEFAULT 0.00,
    `date_p1` DATE NULL,
    `installment_p2` DECIMAL(10,2) NOT NULL DEFAULT 0.00,
    `date_p2` DATE NULL,
    `installment_p3` DECIMAL(10,2) NOT NULL DEFAULT 0.00,
    `date_p3` DATE NULL,
    `total_paid` DECIMAL(10,2) NOT NULL DEFAULT 0.00,
    `dues` DECIMAL(10,2) NOT NULL DEFAULT 0.00,
    `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT `fk_payroll_staff` FOREIGN KEY (`staff_id`) REFERENCES `staff_members` (`id`) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE `campus_expenses` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `expense_type` ENUM('rent', 'utility', 'maintenance', 'other') NOT NULL DEFAULT 'rent',
    `month_name` VARCHAR(30) NOT NULL,
    `year_num` INT NOT NULL,
    `amount_due` DECIMAL(10,2) NOT NULL DEFAULT 0.00,
    `amount_paid` DECIMAL(10,2) NOT NULL DEFAULT 0.00,
    `payment_date` DATE NULL,
    `balance_dues` DECIMAL(10,2) NOT NULL DEFAULT 0.00,
    `payee_name` VARCHAR(150) NOT NULL DEFAULT 'Campus Landlord',
    `notes` TEXT NULL,
    `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE `capital_assets` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `asset_name` VARCHAR(150) NOT NULL,
    `specification` VARCHAR(255) NULL,
    `units_count` INT NOT NULL DEFAULT 1,
    `total_cost` DECIMAL(10,2) NOT NULL DEFAULT 0.00,
    `total_paid` DECIMAL(10,2) NOT NULL DEFAULT 0.00,
    `dues` DECIMAL(10,2) NOT NULL DEFAULT 0.00,
    `purchase_date` DATE NULL,
    `vendor_name` VARCHAR(150) NULL,
    `status` ENUM('operational', 'under_installation', 'retired') NOT NULL DEFAULT 'operational',
    `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE `asset_payment_installments` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `asset_id` INT NOT NULL,
    `payment_date` DATE NULL,
    `amount_paid` DECIMAL(10,2) NOT NULL DEFAULT 0.00,
    `remarks` VARCHAR(255) NULL,
    `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT `fk_asset_tx` FOREIGN KEY (`asset_id`) REFERENCES `capital_assets` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE `loans_and_advances` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `borrower_name` VARCHAR(150) NOT NULL,
    `amount_disbursed` DECIMAL(10,2) NOT NULL DEFAULT 0.00,
    `amount_repaid` DECIMAL(10,2) NOT NULL DEFAULT 0.00,
    `balance_due` DECIMAL(10,2) NOT NULL DEFAULT 0.00,
    `purpose` VARCHAR(200) NULL,
    `disbursement_date` DATE NULL,
    `status` ENUM('pending', 'partially_paid', 'settled') NOT NULL DEFAULT 'pending',
    `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE `users` (
    `email` VARCHAR(100) NULL,
    `phone` VARCHAR(30) NULL,
    `must_change_password` TINYINT(1) NOT NULL DEFAULT 0,
    `student_id` INT NULL,
    `profile_photo` VARCHAR(255) NULL,
    `privacy_hide_phone` TINYINT(1) NOT NULL DEFAULT 0,
    `privacy_hide_email` TINYINT(1) NOT NULL DEFAULT 0,
    `last_login_at` DATETIME NULL,
    `last_login_ip` VARCHAR(45) NULL,

    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `username` VARCHAR(50) NOT NULL UNIQUE,
    `password_hash` VARCHAR(255) NOT NULL,
    `full_name` VARCHAR(100) NOT NULL,
    `role` ENUM('admin', 'accountant', 'registrar', 'staff') NOT NULL DEFAULT 'staff',
    `is_active` BOOLEAN NOT NULL DEFAULT TRUE,
    `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    `updated_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE IF NOT EXISTS `login_attempts` (
    `id` BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    `identifier` VARCHAR(255) NOT NULL,
    `ip_address` VARCHAR(45) NOT NULL,
    `attempted_at` DATETIME NOT NULL,
    INDEX `idx_login_identifier_time` (`identifier`, `attempted_at`),
    INDEX `idx_login_ip_time` (`ip_address`, `attempted_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `password_resets` (
    `id` BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    `user_id` INT NOT NULL,
    `token_hash` CHAR(64) NOT NULL UNIQUE,
    `expires_at` DATETIME NOT NULL,
    `used` TINYINT(1) NOT NULL DEFAULT 0,
    INDEX `idx_reset_user` (`user_id`),
    CONSTRAINT `fk_reset_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

